using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("playing=" + EditorApplication.isPlaying + " paused=" + EditorApplication.isPaused + " time=" + Time.time);
            var t = typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView");
            if (t != null)
            {
                var view = EditorWindow.GetWindow(t);
                view.Show();
                view.Focus();
            }

            Application.runInBackground = true;
            EditorApplication.QueuePlayerLoopUpdate();
            result.Log("Game View focused");
        }
    }
}
